using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EffectsMinSoulHeatAction", menuName = "Data/Battle/Battle Actions/Sothis/EffectsMinSoulHeat Action")]
public class EffectsMinSoulHeatAction : MinimumSoulHeatAction
{
	[Header("Purify Action")]
	[SerializeField]
	private BattleAction effectBattleAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		IsDistortionHieroglyphActiveDecreaseEffect(base.MinSoulHeatToUse);
		effectBattleAction.CastTargetAmount(target, amount, source);
		if (resetSoulHeatAfterUse)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 7, delegate
			{
				soulHeat.ResetSoulHeat();
			});
		}
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		IsDistortionHieroglyphActiveDecreaseEffect(base.MinSoulHeatToUse);
		effectBattleAction.CastTarget(target, source);
		if (resetSoulHeatAfterUse)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 7, delegate
			{
				soulHeat.ResetSoulHeat();
			});
		}
	}
}
